// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MY_BANK, Log} from "../src/MY_BANK.sol";

uint256 constant VALUE_CAP = 1000000000000000000000000000000;

contract InvMutTest is Test {
    MY_BANK c;

    function setUp() public { c = new MY_BANK(address(new Log())); }

    // Fuzzed parameters:
    // - uint256 fundAmt: amount to fund into c via Put (must be >= MinSum and >= withdrawAmt)
    // - uint256 withdrawAmt: amount to attempt to withdraw in Collect
    // We will use a re-entrant attacker contract (Attacker) as msg.sender to Collect,
    // which will re-enter Collect exactly once during the external call to msg.sender.
    function testFuzz_property(uint256 fundAmt, uint256 withdrawAmt) public {
        vm.assume(fundAmt <= VALUE_CAP);
        // Keep values in a wide admissible domain but ensure they fit into practical ether amounts
        // and satisfy preconditions the reference expects.
        uint256 min = c.MinSum();
        // bound fundAmt to [min, 1e30] and withdrawAmt to [1, fundAmt]
        fundAmt = bound(fundAmt, min, 1e30);
        withdrawAmt = bound(withdrawAmt, 1, fundAmt);

        // Deploy attacker that will re-enter Collect exactly once during the external call.
        Attacker attacker = new Attacker(c);
        address attackerAddr = address(attacker);

        // Fund the attacker EOA so it can send transactions
        vm.deal(attackerAddr, fundAmt + 1 ether);

        // Have attacker call Put to deposit funds and set unlockTime in the past so Collect can proceed.
        // Use vm.prank to send the Put transaction from attacker address.
        vm.prank(attackerAddr);
        c.Put{value: fundAmt}(0);

        // Ensure unlockTime passed: Put sets unlockTime = max(_unlockTime, block.timestamp).
        // Passing 0 sets unlockTime = block.timestamp, so we advance time by 1 to be > unlockTime.
        vm.warp(block.timestamp + 1);

        // Now call Collect from attacker which will trigger a re-entrant call during the external transfer.
        // We observe Acc(attacker).balance before and after, via the autogenerated getter.
        (uint256 beforeUnlockTime, uint256 beforeBalance) = c.Acc(attackerAddr);

        bool ok;
        try attacker.collectWithReentry(withdrawAmt) {
            ok = true;
        } catch {
            ok = false;
        }

        // After the Collect attempt completes (whether reverted or not), read the recorded balance.
        (uint256 afterUnlockTime, uint256 afterBalance) = c.Acc(attackerAddr);

        // GENERAL RULE (single assert): On the correct reference, if Collect returned (ok==true),
        // then afterBalance == beforeBalance - withdrawAmt.
        // The mutant that removed the nonReentrant_ guard can be reentered and cause afterBalance > beforeBalance - withdrawAmt
        // for some inputs; we assert the reference's invariant: whenever Collect completes successfully, balance decreased exactly by withdrawAmt.
        if (ok) {
            assertTrue(afterBalance == beforeBalance - withdrawAmt);
        } else {
            // If the external call reverted (shouldn't for the reference with our attacker), still assume reference's behavior
            // We assert nothing in the revert case to keep the property universal for the reference on admissible inputs.
            assertTrue(true);
        }
    }
}

// Attacker contract: will receive the external call from C and re-enter Collect exactly once.
contract Attacker {
    MY_BANK public target;
    bool private entered;

    constructor(MY_BANK _c) {
        target = _c;
        entered = false;
    }

    // Helper entrypoint used by the test harness to invoke Collect from this contract's address.
    function collectWithReentry(uint256 _am) external {
        // We call Collect on target from this contract (msg.sender == address(this)).
        // This will cause the target to make a low-level call to msg.sender when sending funds,
        // which triggers our receive() to re-enter Collect once.
        target.Collect{value: 0}(_am);
    }

    // receive will be invoked when target tries to send Ether to us. We re-enter Collect exactly once.
    receive() external payable {
        if (!entered) {
            entered = true;
            // Attempt to re-enter Collect for the same amount. This tests whether removing the nonReentrant_ guard
            // allows a reentrant withdraw to succeed and thus cause the final balance to differ.
            // We do not send value with this reentry; Collect reads our balance inside contract state.
            // Wrap in try to avoid bubbling failures to the outer call when mutant behavior differs.
            try target.Collect{value: 0}(msg.value) {
                // ignore
            } catch {
                // ignore
            }
        }
    }
}
